"""Complete the authored bank with finite-population, Poisson and mixed-law reasoning."""
from pathlib import Path
import json
B=Path(__file__).resolve().parent
Q=json.loads((B/'s_distributions-questions.json').read_text(encoding='utf-8'))
def q(title,stem,solution,model=None,origin=None):
 d=dict(id='s-distributions-original-'+str(len(Q)+1),title=title,stem=stem,solution=solution,origin=origin or 'Original formula and conceptual examination-style problem',difficulty='Medium to hard',visualDecision='The complete symbolic solution and experiment contract are sufficient.')
 if model:d.update(modelId=model,visualDecision='A compact mechanism-specific companion clarifies the probability dependencies.',visualQualification='The title specifies the companion sample inputs. The written argument supplies this problem’s complete numerical or symbolic result.')
 Q.append(d)
q('A conditional independent-binomial pair',r'Independent $A\sim Bin(4,p)$ and $B\sim Bin(6,p)$ share $0<p<1$. Find $P(A=2\mid A+B=3)$.',r'The ten independent common-p trials have three successes in total. Conditional on this total, their three success positions form a uniform subset. Choosing two positions from the four A positions and one from the six B positions gives $\binom42\binom61/\binom{10}3=36/120=3/10$. Direct cancellation of $p^3q^7$ in the joint-to-total ratio yields the same result. The conditional A law is hypergeometric. If the two groups have different probabilities, the shared factor no longer cancels and the uniform allocation conclusion fails.', 'hypergeometric-small')
q('Compare replacement and depletion',r'For sample size n from N with mark fraction p, compare the variance with and without replacement. What happens when n is one and when n is N?',r'Independent replacement gives variance $np(1-p)$. Without replacement, distinct draw indicators have covariance $-p(1-p)/(N-1)$ for $N>1$, giving variance $np(1-p)(N-n)/(N-1)$. At n equal to one, the variances agree because no preceding draw can have depleted the population. At n equal to N, the without-replacement count is constant, while replacement remains random if $0<p<1$. The finite-population factor is a dependence correction, not a changed one-draw success probability.', 'hypergeometric-small')
q('Identify a hypergeometric mode',r'For a sample of five from twelve items with five marks, locate every modal count using adjacent probabilities.',r'The valid support is zero through five. The adjacent ratio at k is $(5-k)(5-k)/[(k+1)(12-5-5+k+1)]=(5-k)^2/[(k+1)(k+3)]$. At k equal to one it is two; at k equal to two it is $9/15<1$. At zero it is also above one and the ratio continues decreasing over the valid range. Therefore the unique mode is two. The floor formula gives $\lfloor(5+1)(5+1)/(12+2)\rfloor=2$, but the ratio argument also checks ties and support boundaries.', 'hypergeometric-mode')
q('A finite-population success wait',r'Randomly order seven items, of which three are marked. Let T be the position of the second mark. Find its support, $P(T=4)$, mean and variance.',r'The second mark can occur at positions two through six. To have T equal to four, choose one earlier mark among the first three positions and one later mark among positions five through seven. This gives $3\cdot3=9$ mark-position sets out of $\binom73=35$, so the probability is $9/35$. Uniform-subset order-statistic formulas give $E[T]=2(8)/4=4$ and $Var(T)=2(3-2+1)(8)(7-3)/(4^2\cdot5)=8/5$. A constant-p negative-binomial law would have unbounded support and different moments.', 'finite-wait')
q('Last marked position',r'Four marked items are randomly positioned among ten slots. Find the expected position of the last mark and the expected number of unmarked slots after it.',r'The five gaps before, between and after the four marks form a uniform weak composition of the six unmarked slots. Symmetry gives mean $6/5$ for each gap, including the final gap. Hence the last marked position has mean $10-6/5=44/5$, agreeing with $r(N+1)/(K+1)=4(11)/5$. Independence of the gaps is not needed for this expectation and is false because their sum is fixed. Treating the final gap as geometric ignores its bounded support and the fixed population.')
q('Derive finite-wait gap covariance',r'In a uniform arrangement of K marks and M unmarked items, let $G_0,\ldots,G_K$ be the unmarked gaps. Derive their pair covariance from symmetry and fixed sum.',r'Write $d=K+1$. Each gap has variance $M(d-1)(M+d)/[d^2(d+1)]$ from the uniform-composition factorial-moment calculation. Since their sum is deterministically M, its variance is zero. Exchangeability gives $0=dv+d(d-1)c$, hence $c=-v/(d-1)=-M(M+d)/[d^2(d+1)]$ for $d>1$. Covariance is negative: a longer gap leaves fewer slots for the others. The fixed-sum identity determines covariance after the one-gap variance is known; it does not imply independent gaps.', 'finite-wait')
q('A finite wait–count dual event',r'In a random ordering of twelve objects with four marks, find the probability that the third mark appears by position six.',r'The third mark has appeared by six exactly when the first six contain at least three marks. Their count is hypergeometric, so the probability is $[\binom43\binom83+\binom44\binom82]/\binom{12}6=(224+28)/924=3/11$. This event relation mirrors binomial count–wait duality, but its fixed-horizon count uses depletion rather than independent replacement. Taking a negative-binomial CDF with p equal to $4/12$ would substitute a different experiment and miss the finite-population constraint.')
q('Translate a Poisson rate into exposure',r'Events follow a homogeneous Poisson model with rate $3/2$ per hour. Find the probability of two events in forty minutes and explain the units.',r'Forty minutes is $2/3$ hour. The dimensionless expected count is $\lambda=(3/2)(2/3)=1$. Thus the two-event probability is $e^{-1}/2$. Inserting forty directly into the hourly rate would give sixty, an incorrect parameter caused by inconsistent units. The Poisson statement also needs the process model or a justified approximation; an observed average rate of $3/2$ by itself does not establish Poisson counts. The exposure specifies the interval, while the rate describes count intensity per unit time.', 'poisson-one')
q('Recover a Poisson parameter from a ratio',r'For a Poisson count X, $P(X=4)=3P(X=3)>0$. Find its parameter and modes.',r'The neighboring mass ratio is $\lambda/(k+1)$, so at k equal to three the given ratio gives $\lambda/4=3$ and $\lambda=12$. For a positive integer parameter, masses at eleven and twelve tie: the ratio reaches one when k is eleven. Earlier ratios exceed one and later ratios are below one. Thus both counts eleven and twelve are modes. The mean twelve does not identify a unique mode. The parameter zero case is excluded by the positive probability assumption.')
q('A Poisson parity identity',r'For $X\sim Pois(\lambda)$, derive the even-count probability and evaluate it at $\lambda=1$.',r'The PGF is $G(z)=\exp(\lambda(z-1))$. At z equal to minus one it gives $E[(-1)^X]=e^{-2\lambda}$, the difference between even and odd probabilities. Together with their sum one, this yields $P(X\text{ even})=(1+e^{-2\lambda})/2$. At parameter one the answer is $(1+e^{-2})/2$. The expression approaches one half as the parameter grows but exceeds it for every finite positive parameter. Counting infinitely many even and odd indices does not assign equal total probability.')
q('A Poisson fourth moment',r'Derive $E[X^4]$ for a Poisson variable of parameter $\lambda$.',r'The factorial moments are $E[(X)_j]=\lambda^j$. Expand the polynomial as $X^4=(X)_4+6(X)_3+7(X)_2+X$, which can be checked by expanding each falling factorial. Therefore $E[X^4]=\lambda^4+6\lambda^3+7\lambda^2+\lambda$. The derivative order and the ordinary exponent cannot be interchanged: the fourth PGF derivative at one gives only the fourth falling-factorial moment. At parameter zero every term vanishes, consistent with a constant zero variable. This method avoids an infinite direct sum while retaining repeated-index corrections.')
q('Condition independent Poisson counts on their sum',r'Independent Poisson counts have parameters two and three. Given that their sum is four, find the probability the first equals one.',r'For first count a and total four, the joint mass is $e^{-5}2^a3^{4-a}/[a!(4-a)!]$. Divide by the total mass $e^{-5}5^4/4!$ to obtain a binomial law with four trials and probability $2/5$. At a equal to one its probability is $4(2/5)(3/5)^3=216/625$. The counts are independent before conditioning but constrained to sum to four afterward. A conditional joint calculation must not retain their original independence.', 'poisson-conditional', 'Reconstructed Oxford PGF and conditional-count exercise type with independently chosen parameters')
q('Unconditional Poisson splitting',r'A Poisson count has parameter six. Independently label each event A with probability $1/3$ and B otherwise. Find the joint PGF and covariance of the two counts.',r'Given total N, the joint PGF is $(z/3+2w/3)^N$. Averaging over the Poisson law gives $\exp[6(z/3+2w/3-1)]=\exp[2(z-1)]\exp[4(w-1)]$. The factorization establishes independent Poisson marginals with parameters two and four, so covariance is zero. At a fixed total n the covariance would be $-n(1/3)(2/3)$; randomness of the Poisson total contributes an equal positive term that cancels it. Conditional and unconditional independence must be distinguished.', 'poisson-splitting')
q('Three-label thinning with discarded events',r'An original Poisson count has parameter ten. Events are independently kept as A with probability $1/5$, kept as B with probability $3/10$, or discarded. Find $P(A=1,B=2)$.',r'The remaining discard probability is one half. The joint PGF factors into Poisson components with parameters two, three and five. Thus A and B are independent and $P(A=1,B=2)=(2e^{-2})(9e^{-3}/2)=9e^{-5}$. Discarding does not require conditioning on the number kept; such conditioning would induce an allocation constraint. The independent-label assumption is essential: a rule that keeps exactly a predetermined number would have a different joint law.', 'poisson-splitting')
q('Mix over a random intensity',r'Choose $\Lambda=1$ or $3$ equally, then sample a Poisson count conditional on it. Find the mean, variance and zero probability.',r'The mean intensity is two and its variance is one. Total expectation and total variance give $E[X]=2$ and $Var(X)=E[\Lambda]+Var(\Lambda)=3$. Its zero probability is $(e^{-1}+e^{-3})/2$, not $e^{-2}$. A random-rate Poisson mixture usually has overdispersion relative to its mean, even though each conditional count has equal mean and variance. The hidden rate varies between experiments, not necessarily within an observed experiment. Replacing it by its average loses both mixture probabilities and extra uncertainty.', 'mixed-poisson')
q('Equal mean and variance do not identify Poisson',r'A variable takes values zero and two with equal probabilities. Compare it with a Poisson law using its first two moments and its support.',r'Its mean is one and second moment two, giving variance one. A Poisson law with parameter one has the same first two moments, but it assigns positive probability to every nonnegative integer, including one, which this variable never takes. Therefore equality of mean and variance is a useful diagnostic but not a characterization. A model requires additional structural assumptions or the full PMF or PGF. The counterexample is also a warning against identifying a law from only a few summary statistics.')
q('A zero-truncated Poisson count',r'For $X\sim Pois(\lambda)$ with $\lambda>0$, derive its mean and variance given $X>0$.',r'The retained probability is $d=1-e^{-\lambda}$. Zero contributes nothing to the first two raw moments, so the conditional mean is $\lambda/d$ and second moment is $(\lambda^2+\lambda)/d$. Subtraction gives $Var(X\mid X>0)=\lambda/d-\lambda^2e^{-\lambda}/d^2$. This law has positive support and differs from simply adding one to an ordinary Poisson variable. For tiny lambda, stable computation of d is needed; mathematically the conditioned distribution approaches a point mass at one as lambda tends to zero.')
q('Size bias changes a count law',r'An observed Poisson count is sampled with probability proportional to its count, so its new PMF is $kP(X=k)/E[X]$. Identify the resulting distribution for positive parameter.',r'The size-biased mass at positive k is $k e^{-\lambda}\lambda^k/(k!\lambda)=e^{-\lambda}\lambda^{k-1}/(k-1)!$. Hence the observed variable equals one plus a Poisson variable of the same parameter. Its mean is $1+\lambda$ and variance lambda. The zero mass disappears because a zero-count object cannot be selected by this rule. This is different from conditioning on positivity, which renormalizes each positive mass uniformly rather than multiplying it by its count.')
q('A finite sum is not a scaled copy',r'For independent Poisson variables X1 and X2 of parameter two, compare $X_1+X_2$ with $2X_1$.',r'Independence gives $X_1+X_2\sim Pois(4)$, with mean and variance four and full nonnegative-integer support. The scaled copy has mean four, variance $4Var(X_1)=8$, and support restricted to even integers. Its PGF is $G_{X_1}(z^2)$, while the independent sum uses $G_{X_1}(z)^2$. Similar notation for addition and multiplication can hide distinct dependence structures. The means agreeing is not evidence of equal distributions or equal variances.')
q('A rare-event approximation with a checked error',r'For $X\sim Bin(200,1/200)$, write the exact probability of at most one success, the Poisson approximation and a rigorous absolute error bound.',r'The exact probability is $(199/200)^{200}+(199/200)^{199}$. With parameter $np=1$, the Poisson approximation is $2e^{-1}$. Coupling each Bernoulli coordinate with an independent Poisson coordinate gives an event-probability error bounded by $\sum p_i^2=200/200^2=1/200$. The event probability, rather than each mass separately, obeys this bound. It is an absolute bound and does not imply a small relative error for a rare event. A printed rule of thumb about n and p alone is weaker than this quantified statement.', 'poisson-approximation')
q('A bound for heterogeneous rare trials',r'Independent trials have probabilities $0.01,0.02,0.03$. Approximate their no-success probability and give a bound without treating them as identically distributed.',r'The exact probability is $0.99\cdot0.98\cdot0.97=0.941094$. The Poisson parameter is the probability sum, $0.06$, so the approximation is $e^{-0.06}$, about $0.9417645$. The coupling bound is $0.01^2+0.02^2+0.03^2=0.0014$, which exceeds the actual absolute discrepancy of about $0.0006705$. No common probability was assumed. Using $Bin(3,0.02)$ as if it were exact would introduce a different approximation before the Poisson step.', 'heterogeneous')
q('Prove the one-coordinate coupling distance',r'Compute the total-variation distance between a Bernoulli variable of parameter p and a Poisson variable of parameter p, for $0\le p\le1$.',r'At zero, the Poisson mass $e^{-p}$ is at least $1-p$ by the exponential inequality. At one, Bernoulli has excess mass $p-pe^{-p}$. At all larger indices, only Poisson has positive mass. Total variation is the sum of the positive Bernoulli excesses, so it equals $p(1-e^{-p})\le p^2$. Matching the shared masses at each index constructs a coupling with this discrepancy probability. The bound is not an equality in general; the exact distance is the first expression. It compares laws, not numerical simulations.')
q('A fixed-k limit is not uniform over moving k',r'For $X_n\sim Bin(n,\lambda/n)$, explain why pointwise convergence of $P(X_n=k)$ for each fixed k does not by itself certify an approximation at $k=n$.',r'The standard limit holds k fixed while n grows; its finite product and factorial approximations rely on that regime. A moving count k equal to n is not covered by those steps. The binomial mass there is $(\lambda/n)^n$, while the Poisson mass is $e^{-\lambda}\lambda^n/n!$, with a ratio involving $n!/n^n$ that changes drastically. Both masses can be tiny, so absolute and relative errors tell different stories. A uniform event bound needs a separate coupling or total-variation argument, not a relabeled pointwise proof.')
q('Shared dependence can break rare-event reasoning',r'Let each of n indicators equal the same Bernoulli variable B of parameter $1/n$. Does their sum approach a Poisson law of parameter one?',r'The sum is nB, so it is zero with probability $1-1/n$ and n with probability $1/n$. Every individual probability is small and the mean sum is one, yet the all-zero probability tends to one instead of $e^{-1}$. The indicators are perfectly dependent. The independent-coordinate coupling bound cannot be applied. Even the mean fails to pass to the limiting constant-zero law because the rare n-sized values retain mean one. Small marginals and a matched intensity do not establish Poisson approximation.')
q('A small-interval process statement',r'A homogeneous Poisson process has rate $\rho$. Is its count in an interval of positive length h exactly Bernoulli? State the correct small-h relations.',r'The interval count is Poisson with parameter $\rho h$ and has positive probability of two or more events whenever $\rho h>0$. Therefore it is not exactly Bernoulli. Its one-event probability is $\rho h e^{-\rho h}=\rho h+O(h^2)$, and its multiple-event probability is $1-e^{-\rho h}(1+\rho h)=O(h^2)$. Together with independent disjoint increments, these asymptotic relations support the process limit. Describing an arbitrarily short finite interval as exactly binary silently drops nonzero mass.', 'poisson-small-interval')
q('A discrete uniform transform',r'Let X be uniform on integers one through m, and set $Y=2X-3$. Find support, mean and variance, and decide whether Y is uniform on every integer between its endpoints.',r'The image support is $-1,1,3,\ldots,2m-3$, with mass $1/m$ at each image because the transform is injective. The mean is $2(m+1)/2-3=m-2$, and variance is $4(m^2-1)/12=(m^2-1)/3$. Y is uniform on this arithmetic progression, not on all intervening integers: even indices have zero probability. An affine transform preserves equal atom weights but can change lattice spacing. At m equal to one, the variable is constant and variance is zero.', 'uniform-lattice')
q('An integer threshold under a lattice transform',r'For X uniform on one through eight and $Y=3X+1$, find $P(8<Y\le20)$ and $E[Y\mid8<Y\le20]$.',r'The inequalities become $7/3<X\le19/3$, so the admissible integers are three through six. Four of the eight equally likely values qualify, giving probability one half. Their transformed values are ten, thirteen, sixteen and nineteen, whose conditional mean is $58/4=29/2$. The conditional X mean is $9/2$, and applying the affine map gives the same result. Rounding both original thresholds in the same direction would include or exclude an incorrect boundary atom.')
q('Normalization at a binomial endpoint',r'What are the laws of a binomial count with $n=0$, and of a count with $n=5,p=1$? Why should a software implementation avoid evaluating a general log-mass formula first?',r'The empty count at n equal to zero is deterministically zero, regardless of p. With five certain successes, the count is deterministically five. The general log expression contains logarithms of p and $1-p$ and products such as zero times the logarithm of zero, which floating-point arithmetic may treat as undefined. Handle deterministic endpoint laws before logarithms or factorial ratios. This is a boundary interpretation of a valid experiment, not a numerical patch that changes its probability.')
q('Compute a stable tiny tail',r'For $X\sim Bin(n,p)$ with very small p, explain how to compute $P(X\ge1)$ without cancellation, and distinguish numerical error from modeling error.',r'The exact probability is $1-(1-p)^n$. Compute it as $-\operatorname{expm1}(n\operatorname{log1p}(-p))$, using routines designed for tiny arguments. Direct subtraction from one can lose significant digits when the no-success probability rounds near one. This stable formula still describes an independent common-p binomial model. Replacing it by $1-e^{-np}$ introduces Poisson modeling approximation in addition to numerical evaluation. Good numerical routines do not validate the experimental assumptions or make an approximation exact.')
q('Infer a law from a PGF coefficient pattern',r'A count has PGF $G(z)=(2+z)^5/3^5$. Identify its law and obtain $P(X\le1)$ and $E[X(X-1)]$.',r'Writing the factor as $2/3+z/3$ identifies $Bin(5,1/3)$. The zero mass is $32/243$, and the one mass is $5(1/3)(2/3)^4=80/243$, so the requested lower-tail probability is $112/243$. The second derivative at one is $5\cdot4/9=20/9$, the second falling-factorial moment. It is not the variance; variance is $5(1/3)(2/3)=10/9$. A PGF gives both coefficients and derivatives, but their meanings must remain distinct.')
q('A random-sum model',r'A Poisson number N of parameter two determines how many independent fair Bernoulli marks are summed. Find the resulting count law and distinguish this from $NB$ for a single common mark.',r'Independent fresh marks give PGF $G_N((1+z)/2)=\exp(z-1)$, so the result is Poisson with parameter one. A single common fair mark B instead yields a mixture: zero if B is zero and the entire Poisson count if B is one. Its zero probability is $(1+e^{-2})/2$, not $e^{-1}$, and its variance is two rather than one. Random-sum composition requires independent summands and independence of the summands from N; repeating the same mark creates dependence.', 'poisson-splitting')
q('Conditional law under a zero observation',r'A failure-based geometric family-size prior has parameter one half. Each child independently passes an observation test with probability one half. Given zero passing children, derive the posterior family-size law.',r'The prior mass at n is $2^{-n-1}$ and the likelihood of zero passes is $2^{-n}$. Their product is $(1/2)4^{-n}$. The sum over all nonnegative n is $2/3$, so the posterior mass is $(3/4)(1/4)^n$, a failure-based geometric law of parameter $3/4$. Its positive-size probability is $1/4$ and mean $1/3$. The zero-size case satisfies the observation automatically and must be retained. Updating individual outcomes without reweighting family sizes misses the selection effect.', 'family-posterior')
q('Why factorial moments do not justify an arbitrary law',r'An investigator knows $E[X]=2$ for an integer count but assumes $E[X(X-1)]=4$ because a Poisson variable has that value. Diagnose the inference and give a counterexample.',r'A Poisson variable of mean two does have second falling-factorial moment four. However, the constant count X equal to two has the same mean and falling-factorial moment two, not four. Its variance is zero rather than two. The identity $E[X^2]=E[X(X-1)]+E[X]$ holds for any variable with finite second moment; substituting a Poisson-specific factorial moment requires establishing the Poisson law first. A mean is an expectation constraint, not a generating-function or full-distribution specification.')
q('Choose the family before calculating',r'Classify three experiments: successes in eight independent attempts with common p; attempts through the third success; and marks among eight objects drawn without replacement from a finite population.',r'The first is a fixed-horizon binomial count with support zero through eight. The second is a total-trial negative-binomial wait with support three onward when $0<p<1$; its last attempt must succeed. The third is hypergeometric with support bounded by both marked and unmarked pools. The number eight names different quantities in the first and third experiments, and there is no deterministic eight-attempt horizon in the second. Correct classification precedes selecting a coefficient, moment formula or tail expression.')
q('Conditioning on an impossible event',r'For $X\sim Bin(4,0)$, can one calculate $P(X=1\mid X>0)$ by continuity from positive p? Is that an ordinary conditional probability in the stated experiment?',r'At p equal to zero, X is identically zero and $P(X>0)=0$. The usual finite-event conditional ratio is therefore undefined. For positive p, the conditional probability is $4p(1-p)^3/[1-(1-p)^4]$, whose limit is one as p approaches zero. That limiting conditional law is a different construction and must be labeled as such. An algebraic limit does not assign a uniquely determined event conditional within a model where the conditioning event has zero probability.')
q('A Poisson count conditioned by a parity observation',r'For positive $\lambda$, derive $E[X\mid X\text{ even}]$ when X is Poisson.',r'Use $E[X(-1)^X]=(-1)G^{\prime}(-1)=-\lambda e^{-2\lambda}$. Since the even indicator equals $(1+(-1)^X)/2$, the even-conditioned first-moment numerator is $\lambda(1-e^{-2\lambda})/2$. Divide by the even probability $(1+e^{-2\lambda})/2$ to obtain $\lambda(1-e^{-2\lambda})/(1+e^{-2\lambda})$. The support contains only even integers, so the conditional law is not Poisson even though its calculation uses the original PGF. Differentiating at minus one requires the extra z factor for $E[Xz^X]$.')
q('A binomial sample conditioned on parity',r'For $X\sim Bin(3,1/2)$, find its law and variance conditional on an even count.',r'Only zero and two are admissible. Their original masses are $1/8$ and $3/8$, totaling one half. The conditional masses are therefore $1/4$ and $3/4$, with mean $3/2$, second moment three and variance $3/4$. These moments match the original fair binomial, yet the conditional support is different. This reinforces that even matching both mean and variance does not identify a named family. Conditioning must be applied to each retained atom before computing centered moments.')
q('A direct hypergeometric second factorial moment',r'For a uniform n-subset of N objects with K marks, derive $E[X(X-1)]$ and use it to recover variance.',r'For each ordered pair of distinct sample positions, both are marked with probability $K(K-1)/[N(N-1)]$ when $N>1$. There are $n(n-1)$ ordered pairs, so the falling-factorial moment is $n(n-1)K(K-1)/[N(N-1)]$. Add the mean $nK/N$ to get the second raw moment and subtract the squared mean. Simplification yields $n(K/N)(1-K/N)(N-n)/(N-1)$. Ordered pairs explain the absence of a factor one half; unordered pairs instead correspond to $\binom X2$.', 'hypergeometric-small')
q('A posterior rate mixture after no events',r'A hidden Poisson parameter is one or three with equal prior weights. Given a zero count in one exposure, find the probability the parameter was one and the next equal-exposure expected count.',r'The zero likelihoods are $e^{-1}$ and $e^{-3}$. Bayes normalization gives posterior low-rate weight $e^{-1}/(e^{-1}+e^{-3})=e^2/(e^2+1)$. If the next count is conditionally independent given the same hidden parameter, its predictive mean is $(e^2+3)/(e^2+1)$. This is below the prior mean two because a quiet exposure favors the low-rate regime. Independent increments conditional on an unknown shared rate do not imply unconditional independent observations. Resetting the hidden parameter between exposures would change the predictive update.', 'mixed-poisson')
q('Repeated until a sampled batch is acceptable',r'Independent batches each contain four fair trials. Continue sampling batches until a batch has at least two successes. Find the expected number of batches and expected total number of trials.',r'One batch is acceptable with probability $1-P(X=0)-P(X=1)=1-1/16-4/16=11/16$. Independent batches create a positive geometric batch wait with mean $16/11$. Each batch always contains four trials, so total trials equal four times the batch count and have mean $64/11$. Stopping within a batch at the second success would be a different experiment. A deterministic batch cost can be multiplied outside expectation; a random cost dependent on acceptability needs more careful accounting.')
q('Stop at the first success among a finite set',r'A random permutation of N items contains exactly one mark. Compare its first-mark position law with an independent geometric wait of success probability $1/N$.',r'The unique marked position is uniform on one through N. Its mean is $(N+1)/2$ and variance $(N^2-1)/12$. An independent replacement wait with probability $1/N$ instead has mean N, variance $N(N-1)$ and unbounded support. Both experiments have initial success probability $1/N$, but after a failed finite-population draw the success hazard rises to $1/(N-i+1)$. One initial probability does not determine a waiting-time law; how the population or trial process changes afterward matters.', 'finite-one-mark')
q('Assess an approximation at impossible finite counts',r'A binomial count has n trials, and a Poisson approximation uses parameter np. What should be reported for a requested probability above n?',r'The exact binomial probability of a count above n is zero by support. The Poisson approximation assigns a positive tail there when np is positive, because its support is unbounded. If the task asks for the exact answer, report zero before computing any approximation. If it asks to study approximation quality, the Poisson tail is an explicit mismatch and contributes to total variation. An approximation does not alter the support of the original experiment. Absolute smallness may make the tail tolerable for some uses, but it cannot justify describing it as exact.')
assert len(Q)==85, len(Q)
for d in Q:
 assert d['stem'] and len(d['solution'])>=300,(d['id'],len(d['solution']))
(B/'s_distributions-questions.json').write_text(json.dumps(Q,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Completed 85 individually explained formula and conceptual problems.')
